import{_ as t,o as n,c as i,a6 as e}from"./chunks/framework.DycQjAfF.js";const k=JSON.parse('{"title":"Menentukan Fast & Slow Moving","description":"Mengklasifikasikan material dari frekuensi permintaan dalam sebulan.","frontmatter":{"title":"Menentukan Fast & Slow Moving","description":"Mengklasifikasikan material dari frekuensi permintaan dalam sebulan.","status":"draf","dasar":"kriteria dari materi presentasi Gudang Teknik (slide 9)","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Tutorial","tingkat":"Pemula","sumber":["ppt-gudang-teknik"],"kata_kunci":["tutorial","fast moving","slow moving","klasifikasi","frekuensi permintaan","reservasi","cycle counting"]},"headers":[],"relativePath":"tutorial/fast-slow-moving.md","filePath":"tutorial/fast-slow-moving.md"}'),l={name:"tutorial/fast-slow-moving.md"};function r(d,a,o,s,u,m){return n(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="menentukan-fast-slow-moving" tabindex="-1">Menentukan Fast &amp; Slow Moving <a class="header-anchor" href="#menentukan-fast-slow-moving" aria-label="Permalink to &quot;Menentukan Fast &amp; Slow Moving&quot;">​</a></h1><p class="lead">Kamu akan mengelompokkan material berdasarkan seberapa sering material itu diminta dalam satu bulan.</p><div class="tip custom-block"><p class="custom-block-title">Sebelum mulai</p><ul><li><strong>Setelah latihan ini, kamu bisa</strong> menghitung frekuensi permintaan dan menerapkan kriteria fast/slow moving.</li><li><strong>Tingkat:</strong> Pemula, sekitar 30 menit.</li><li><strong>Baca dulu:</strong> <a href="/WareHouse/divisi/manajemen-inventory">Manajemen Stok</a>.</li><li><strong>Siapkan:</strong> catatan barang keluar selama satu bulan (untuk praktik nyata, minta ke pembimbing).</li></ul></div><h2 id="kriteria" tabindex="-1">Kriteria <a class="header-anchor" href="#kriteria" aria-label="Permalink to &quot;Kriteria&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kategori</th><th>Frekuensi permintaan per bulan</th></tr></thead><tbody><tr><td data-label="Kategori"><strong>Fast moving</strong></td><td data-label="Frekuensi permintaan per bulan">2 kali atau lebih</td></tr><tr><td data-label="Kategori"><strong>Slow moving</strong></td><td data-label="Frekuensi permintaan per bulan">1 kali</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Yang dihitung adalah frekuensi, bukan jumlah unit</p><p>Satu permintaan berisi 50 baut tetap dihitung <strong>1 kali</strong> permintaan. Material yang diminta sekali dalam jumlah besar tetap termasuk slow moving.</p></div><h2 id="langkah" tabindex="-1">Langkah <a class="header-anchor" href="#langkah" aria-label="Permalink to &quot;Langkah&quot;">​</a></h2><ol><li><strong>Ambil catatan barang keluar</strong> untuk satu bulan penuh.</li><li><strong>Kelompokkan per kode barang.</strong> Gunakan kode, bukan nama, agar barang yang sama tidak terhitung dua kali.</li><li><strong>Hitung berapa kali</strong> setiap kode muncul sebagai permintaan.</li><li><strong>Terapkan kriteria.</strong> 2 kali atau lebih berarti fast moving, 1 kali berarti slow moving.</li><li><strong>Pisahkan yang 0 kali.</strong> Materi belum mengatur kategori untuk material ini. Tanyakan ke pembimbing.</li><li><strong>Tandai yang termasuk critical stock.</strong> Untuk material slow moving yang penting bagi mesin, pastikan stok minimal 1 unit.</li></ol><h2 id="contoh-dengan-data-latihan" tabindex="-1">Contoh dengan data latihan <a class="header-anchor" href="#contoh-dengan-data-latihan" aria-label="Permalink to &quot;Contoh dengan data latihan&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kode (latihan)</th><th>Material</th><th>Jumlah permintaan bulan ini</th><th>Total unit diminta</th><th>Kategori</th></tr></thead><tbody><tr><td data-label="Kode (latihan)"><code>CTH-PPE-007</code></td><td data-label="Material">Sarung tangan kerja</td><td data-label="Jumlah permintaan bulan ini">9 kali</td><td data-label="Total unit diminta">44 pasang</td><td data-label="Kategori">Fast moving</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-CON-012</code></td><td data-label="Material">Cutting disc 4&quot;</td><td data-label="Jumlah permintaan bulan ini">4 kali</td><td data-label="Total unit diminta">20 pcs</td><td data-label="Kategori">Fast moving</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-MEC-001</code></td><td data-label="Material">Bearing 6205-2RS</td><td data-label="Jumlah permintaan bulan ini">2 kali</td><td data-label="Total unit diminta">2 pcs</td><td data-label="Kategori">Fast moving</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-FAS-014</code></td><td data-label="Material">Baut M12 × 50</td><td data-label="Jumlah permintaan bulan ini">1 kali</td><td data-label="Total unit diminta">50 pcs</td><td data-label="Kategori">Slow moving</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-MEC-030</code></td><td data-label="Material">Coupling (contoh)</td><td data-label="Jumlah permintaan bulan ini">0 kali</td><td data-label="Total unit diminta">0</td><td data-label="Kategori">Tanyakan pembimbing</td></tr></tbody></table><p>Perhatikan baris baut: walaupun 50 unit diminta, permintaannya hanya <strong>1 kali</strong>, sehingga baut tersebut termasuk slow moving.</p><h2 id="kesalahan-umum" tabindex="-1">Kesalahan umum <a class="header-anchor" href="#kesalahan-umum" aria-label="Permalink to &quot;Kesalahan umum&quot;">​</a></h2><ul><li>Menghitung unit, bukan frekuensi permintaan.</li><li>Memakai data kurang dari satu bulan.</li><li>Menggabungkan barang yang mirip tetapi berbeda kode.</li></ul><h2 id="hasil-yang-diharapkan" tabindex="-1">Hasil yang diharapkan <a class="header-anchor" href="#hasil-yang-diharapkan" aria-label="Permalink to &quot;Hasil yang diharapkan&quot;">​</a></h2><p>Daftar material dengan kategori fast moving, slow moving, atau &quot;perlu ditanyakan&quot;, yang bisa dipakai sebagai dasar menentukan stok minimum, stok maksimum, dan ROP pada <a href="/WareHouse/tutorial/min-max-rop">tutorial berikutnya</a>.</p>',15)])])}const b=t(l,[["render",r]]);export{k as __pageData,b as default};
